Iterative Code of Binary Search
// program to implement recursive Binary Search
#include <iostream.h>
using namespace std;
int binary_search(int A[], int l, int r, int x)
{
while (l <= r) {
int mid = l + (r - l) / 2;
if (A[mid] == x)
return mid;
if (A[mid] < x) // If x greater, ignore left half
l = mid + 1;
else // If x is smaller, ignore right half
r = mid - 1;
}
