int binary_search(int X, int A[], int left, int right){
if (left == right)
if (X==A[left]) return left;
else return -1;
int mid = (left+right)/2;
if (X==A[mid]) return mid;
if (X < A[mid]) return binarySearch (X, A, left, mid-1);
